-- Readings: short speeches to read aloud, one level each, in phrase lines.
--
-- Generated by drizzle-kit, then made idempotent by hand. Purely additive — two
-- new tables. Nothing is dropped and no existing row is touched, so this is safe
-- on a live database.

CREATE TABLE IF NOT EXISTS "reading_lines" (
	"id" text PRIMARY KEY NOT NULL,
	"reading_id" text NOT NULL,
	"index" integer NOT NULL,
	"stanza" integer NOT NULL,
	"text" text NOT NULL,
	"reading_kana" text NOT NULL,
	"furigana" jsonb,
	"translation" text NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "readings" (
	"id" text PRIMARY KEY NOT NULL,
	"language_id" text NOT NULL,
	"level_id" text NOT NULL,
	"code" text NOT NULL,
	"title" text NOT NULL,
	"title_en" text NOT NULL,
	"published" boolean DEFAULT false NOT NULL,
	"sort_index" integer DEFAULT 0 NOT NULL,
	"source_id" text,
	"source_ref" text,
	"source_hash" text,
	"human_edited" boolean DEFAULT false NOT NULL,
	"locked_fields" text[] DEFAULT '{}' NOT NULL,
	"upstream_removed_at" timestamp,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);
--> statement-breakpoint
